  row: { flexDirection: 'row', alignItems: 'center', padding: 12 },
  icon: { marginRight: 12 },
  label: { flex: 1, fontSize: 16 },
  chevron: { color: '#888' },
  pressed: { opacity: 0.75 },
  disabled: { opacity: 0.5 },
